public class MinecoloniesWorldCapabilityProvider
implements ICapabilitySerializable<Tag> {
    private final IChunkmanagerCapability chunkMap = new IChunkmanagerCapability.Impl();
    private final LazyOptional<IChunkmanagerCapability> chunkMapOptional = LazyOptional.of(() -> this.chunkMap);

    public Tag serializeNBT() {
