    @Nonnull
    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> cap, Direction direction) {
        return cap == MineColonies.CHUNK_STORAGE_UPDATE_CAP ? this.chunkMapOptional.cast() : LazyOptional.empty();
    }
}

